use_getxattr(struct dentry *dentry, const char *name, char *value,
		      size_t size)
{
	struct inode *inode = d_inode(dentry);
	struct fuse_conn *fc = get_fuse_conn(inode);
	struct fuse_inode *fi = get_fuse_inode(inode);
	struct fuse_xattr_out outarg;
	struct fuse_getxattr_in inarg;
	int err;

	if (fuse_is_bad(inode))
		return -EIO;

	memset(&inarg, 0, sizeof(inarg));
	memset(&outarg, 0, sizeof(outarg));

	inarg.name = name;
	inarg.name_len = strlen(name);
	inarg.valid = FATTR_XATTR;

	err = fuse_simple_request(get_fuse_mount(inode), &args);
	if (!err) {
		if (fuse_invalid_attr(&outarg.xattr))
			err = -ENOENT;
		else {
			if (size < outarg.xattr.size)
				err = -ERANGE;
			else {
				memcpy(value, outarg.xattr.value,
				       outarg.xattr.size);
				err = 0;
			}
		}
	}
	return err;
}

